package main

import (
	"flag"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

var (
	packageName    = flag.String("p", "myservice", "Package under which code will be generated")
	outputFile     = flag.String("o", "myservice.go", "File where the generated code will be saved")
	directory      = flag.String("d", "./", "Directory under which package directory will be created")
	skipVerify     = flag.Bool("i", false, "Skips TLS Verification")
	makePublic     = flag.Bool("make-public", true, "Make the generated types public/exported")
	showVersion    = flag.Bool("v", false, "Shows gowsdl version")
)

const version = "v0.5.0"

func main() {
	flag.Parse()

	if *showVersion {
		fmt.Println("🍀  " + version)
		return
	}

	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		os.Exit(1)
	}

	wsdlFile := args[0]

	// Read WSDL file
	var wsdlContent []byte
	var err error

	if strings.HasPrefix(wsdlFile, "http://") || strings.HasPrefix(wsdlFile, "https://") {
		fmt.Printf("🍀  Downloading file %s\n", wsdlFile)
		wsdlContent, err = downloadFile(wsdlFile)
	} else {
		fmt.Printf("🍀  Reading file %s\n", wsdlFile)
		wsdlContent, err = os.ReadFile(wsdlFile)
	}

	if err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}

	fmt.Println("🍀  Done 👍")

	// Parse WSDL
	wsdl, err := parseWSDL(wsdlContent)
	if err != nil {
		fmt.Printf("Error parsing WSDL: %v\n", err)
		os.Exit(1)
	}

	// Generate code
	clientCode, serverCode := generateCode(wsdl, *packageName, *makePublic, string(wsdlContent))

	// Create output directories
	outputDir := filepath.Join(*directory, *packageName)
	err = os.MkdirAll(outputDir, 0755)
	if err != nil {
		fmt.Printf("Error creating directory: %v\n", err)
		os.Exit(1)
	}

	// Write client code
	clientPath := filepath.Join(outputDir, *outputFile)
	err = os.WriteFile(clientPath, []byte(clientCode), 0644)
	if err != nil {
		fmt.Printf("Error writing client file: %v\n", err)
		os.Exit(1)
	}

	// Write server code
	serverPath := filepath.Join(outputDir, "server"+*outputFile)
	err = os.WriteFile(serverPath, []byte(serverCode), 0644)
	if err != nil {
		fmt.Printf("Error writing server file: %v\n", err)
		os.Exit(1)
	}
}

func downloadFile(url string) ([]byte, error) {
	client := &http.Client{}
	resp, err := client.Get(url)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	return io.ReadAll(resp.Body)
}

func parseWSDL(content []byte) (interface{}, error) {
	// Placeholder for WSDL parsing
	// This will be implemented in the next step
	return nil, nil
}

func generateCode(wsdl interface{}, packageName string, makePublic bool, wsdlContent string) (string, string) {
	// Placeholder for code generation
	// This will be implemented in the next step
	return "", ""
}
EOF

