package main

import (
	"encoding/xml"
	"strings"
)

// WSDL represents the parsed WSDL structure
type WSDL struct {
	XMLName       xml.Name
	TargetNamespace string
	Types         *Types `xml:"types"`
	Messages      []Message `xml:"message"`
	PortTypes     []PortType `xml:"portType"`
	Bindings      []Binding `xml:"binding"`
	Services      []Service `xml:"service"`
}

// Types contains schema definitions
type Types struct {
	XMLName xml.Name
	Schemas []Schema `xml:"schema"`
}

// Schema represents an XML schema
type Schema struct {
	XMLName           xml.Name
	TargetNamespace   string `xml:"targetNamespace,attr"`
	Elements          []Element `xml:"element"`
	ComplexTypes      []ComplexType `xml:"complexType"`
	SimpleTypes       []SimpleType `xml:"simpleType"`
	Attributes        []Attribute `xml:"attribute"`
}

// Element represents an XML element
type Element struct {
	XMLName    xml.Name
	Name       string `xml:"name,attr"`
	Type       string `xml:"type,attr"`
	MinOccurs  string `xml:"minOccurs,attr"`
	MaxOccurs  string `xml:"maxOccurs,attr"`
	Inner      string `xml:",innerxml"`
	ComplexType *ComplexType `xml:"complexType"`
	SimpleType  *SimpleType `xml:"simpleType"`
	Annotation  *Annotation `xml:"annotation"`
}

// ComplexType represents a complex type definition
type ComplexType struct {
	XMLName    xml.Name
	Name       string `xml:"name,attr"`
	Sequence   *Sequence `xml:"sequence"`
	All        *Sequence `xml:"all"`
	SimpleContent *SimpleContent `xml:"simpleContent"`
	Attributes []Attribute `xml:"attribute"`
	Inner      string `xml:",innerxml"`
}

// Sequence represents a sequence of elements
type Sequence struct {
	XMLName  xml.Name
	Elements []Element `xml:"element"`
	Inner    string `xml:",innerxml"`
}

// SimpleContent represents simple content with extension
type SimpleContent struct {
	XMLName   xml.Name
	Extension *Extension `xml:"extension"`
}

// Extension represents an extension of a type
type Extension struct {
	XMLName    xml.Name
	Base       string `xml:"base,attr"`
	Attributes []Attribute `xml:"attribute"`
}

// SimpleType represents a simple type definition
type SimpleType struct {
	XMLName     xml.Name
	Name        string `xml:"name,attr"`
	Restriction *Restriction `xml:"restriction"`
}

// Restriction represents a restriction on a simple type
type Restriction struct {
	XMLName      xml.Name
	Base         string `xml:"base,attr"`
	Enumerations []Enumeration `xml:"enumeration"`
	MinLength    string `xml:"minLength,attr"`
	Inner        string `xml:",innerxml"`
}

// Enumeration represents an enum value
type Enumeration struct {
	XMLName     xml.Name
	Value       string `xml:"value,attr"`
	Annotation  *Annotation `xml:"annotation"`
}

// Annotation represents documentation
type Annotation struct {
	XMLName       xml.Name
	Documentation *Documentation `xml:"documentation"`
}

// Documentation represents documentation text
type Documentation struct {
	XMLName xml.Name
	Text    string `xml:",chardata"`
}

// Attribute represents an XML attribute
type Attribute struct {
	XMLName xml.Name
	Name    string `xml:"name,attr"`
	Type    string `xml:"type,attr"`
	Use     string `xml:"use,attr"`
	Ref     string `xml:"ref,attr"`
	SimpleType *SimpleType `xml:"simpleType"`
}

// Message represents a WSDL message
type Message struct {
	XMLName xml.Name
	Name    string `xml:"name,attr"`
	Parts   []Part `xml:"part"`
}

// Part represents a message part
type Part struct {
	XMLName   xml.Name
	Name      string `xml:"name,attr"`
	Element   string `xml:"element,attr"`
	Type      string `xml:"type,attr"`
}

// PortType represents a WSDL port type
type PortType struct {
	XMLName   xml.Name
	Name      string `xml:"name,attr"`
	Operations []Operation `xml:"operation"`
}

// Operation represents a WSDL operation
type Operation struct {
	XMLName xml.Name
	Name    string `xml:"name,attr"`
	Input   OperationPart `xml:"input"`
	Output  OperationPart `xml:"output"`
}

// OperationPart represents input or output of an operation
type OperationPart struct {
	XMLName xml.Name
	Message string `xml:"message,attr"`
}

// Binding represents a WSDL binding
type Binding struct {
	XMLName   xml.Name
	Name      string `xml:"name,attr"`
	Type      string `xml:"type,attr"`
	Operations []BindingOperation `xml:"operation"`
	Inner     string `xml:",innerxml"`
}

// BindingOperation represents an operation in a binding
type BindingOperation struct {
	XMLName xml.Name
	Name    string `xml:"name,attr"`
	Inner   string `xml:",innerxml"`
}

// Service represents a WSDL service
type Service struct {
	XMLName xml.Name
	Name    string `xml:"name,attr"`
	Ports   []Port `xml:"port"`
	Inner   string `xml:",innerxml"`
}

// Port represents a port in a service
type Port struct {
	XMLName xml.Name
	Name    string `xml:"name,attr"`
	Binding string `xml:"binding,attr"`
	Inner   string `xml:",innerxml"`
}

// ParseWSDLContent parses WSDL XML content
func parseWSDL(content []byte) (*WSDL, error) {
	wsdl := &WSDL{}

	// Decode with namespace handling
	decoder := xml.NewDecoder(strings.NewReader(string(content)))

	err := decoder.Decode(wsdl)
	if err != nil {
		return nil, err
	}

	return wsdl, nil
}
