// generateCode generates client and server Go code from parsed WSDL
func generateCode(wsdl *WSDL, packageName string, makePublic bool, wsdlContent string) (string, string) {
	generator := &codeGenerator{
		wsdl:       wsdl,
		packageName: packageName,
		makePublic:  makePublic,
		types:      make(map[string]*TypeInfo),
		wsdlContent: wsdlContent,
	}

	return generator.generateClient(), generator.generateServer()
}

type codeGenerator struct {
	wsdl        *WSDL
	packageName  string
	makePublic   bool
	types       map[string]*TypeInfo
	wsdlContent  string
}

type TypeInfo struct {
	Name       string
	IsPublic   bool
	Fields     []Field
	IsEnum     bool
	EnumValues []EnumValue
	IsInterface bool
	Methods    []Method
}

type Field struct {
	Name       string
	Type       string
	XMLTag     string
	JSONTag    string
	Comment    string
	OmitEmpty  bool
}

type EnumValue struct {
	Name    string
	Value   string
	Comment string
}

type Method struct {
	Name string
	Args []MethodArg
	Return string
}

type MethodArg struct {
	Name string
	Type string
}

func (g *codeGenerator) generateClient() string {
	var sb strings.Builder

	sb.WriteString("// Code generated by gowsdl DO NOT EDIT.\n\n")
	sb.WriteString("package " + g.packageName + "\n\n")
	sb.WriteString("import (\n")
	sb.WriteString("\t\"context\"\n")
	sb.WriteString("\t\"encoding/xml\"\n")
	sb.WriteString("\t\"github.com/hooklift/gowsdl/soap\"\n")
	sb.WriteString("\t\"time\"\n")
	sb.WriteString(")\n\n")
	sb.WriteString("// against \"unused imports\"\n")
	sb.WriteString("var _ time.Time\n")
	sb.WriteString("var _ xml.Name\n\n")

	// Generate type definitions from WSDL
	g.extractTypes()

	// Write basic types
	sb.WriteString("type AnyType struct {\n")
	sb.WriteString("\tInnerXML string `xml:\",innerxml\"`\n")
	sb.WriteString("}\n\n")

	sb.WriteString("type AnyURI string\n\n")
	sb.WriteString("type NCName string\n\n")

	// Write all types
	for _, typeInfo := range g.types {
		sb.WriteString(g.generateType(typeInfo))
	}

	// Write service interfaces and implementations
	sb.WriteString(g.generateServices())

	return sb.String()
}

func (g *codeGenerator) generateServer() string {
	var sb strings.Builder

	sb.WriteString("// Code generated by gowsdl DO NOT EDIT.\n\n")
	sb.WriteString("package " + g.packageName + "\n\n")
	sb.WriteString("import (\n")
	sb.WriteString("\t\"encoding/xml\"\n")
	sb.WriteString("\t\"errors\"\n")
	sb.WriteString("\t\"fmt\"\n")
	sb.WriteString("\t\"net/http\"\n")
	sb.WriteString("\t\"reflect\"\n")
	sb.WriteString("\t\"strings\"\n")
	sb.WriteString(")\n\n")

	// Embed WSDL as string literal
	sb.WriteString("var wsdl = `")
	sb.WriteString(g.wsdlContent)
	sb.WriteString("`\n\n")

	sb.WriteString("var WSDLUndefinedError = errors.New(\"Server was unable to process request. --> Object reference not set to an instance of an object.\")\n\n")

	// Write SOAP envelope structures
	sb.WriteString(g.generateSOAPStructures())

	// Write handler functions
	sb.WriteString(g.generateServerHandlers())

	return sb.String()
}

func (g *codeGenerator) extractTypes() {
	if g.wsdl.Types == nil {
		return
	}

	for _, schema := range g.wsdl.Types.Schemas {
		// Process elements
		for _, elem := range schema.Elements {
			if elem.ComplexType != nil {
				g.processComplexType(elem.Name, elem.ComplexType, schema.TargetNamespace)
			} else if elem.SimpleType != nil {
				g.processSimpleType(elem.Name, elem.SimpleType, schema.TargetNamespace)
			} else if elem.Type != "" {
				// This is a reference to another type
				g.addElementType(elem.Name, elem.Type, schema.TargetNamespace, "")
			}
		}

		// Process complex types
		for _, ct := range schema.ComplexTypes {
			g.processComplexType(ct.Name, &ct, schema.TargetNamespace)
		}

		// Process simple types
		for _, st := range schema.SimpleTypes {
			g.processSimpleType(st.Name, &st, schema.TargetNamespace)
		}
	}
}

func (g *codeGenerator) processComplexType(name string, ct *ComplexType, ns string) {
	if ct == nil {
		return
	}

	typeInfo := &TypeInfo{
		Name:     name,
		IsPublic: g.makePublic || isInitialCapital(name),
		Fields:   []Field{},
	}

	// Process sequence or all elements
	seq := ct.Sequence
	if seq == nil {
		seq = ct.All
	}

	if seq != nil {
		for _, elem := range seq.Elements {
			field := Field{
				Name:    elem.Name,
				Type:    g.goType(elem.Type),
				XMLTag:  elem.Name + ",omitempty",
				JSONTag: elem.Name + ",omitempty",
			}

			if elem.Annotation != nil && elem.Annotation.Documentation != nil {
				field.Comment = elem.Annotation.Documentation.Text
			}

			typeInfo.Fields = append(typeInfo.Fields, field)
		}
	}

	// Handle SimpleContent with extension
	if ct.SimpleContent != nil && ct.SimpleContent.Extension != nil {
		ext := ct.SimpleContent.Extension
		// Add base type handling if needed
		for _, attr := range ext.Attributes {
			field := Field{
				Name:    attr.Name,
				Type:    g.goType(attr.Type),
				XMLTag:  attr.Name + ",attr,omitempty",
				JSONTag: attr.Name + ",omitempty",
			}
			typeInfo.Fields = append(typeInfo.Fields, field)
		}
	}

	// Process attributes
	for _, attr := range ct.Attributes {
		field := Field{
			Name:    attr.Name,
			Type:    g.goType(attr.Type),
			XMLTag:  attr.Name + ",attr,omitempty",
			JSONTag: attr.Name + ",omitempty",
		}
		typeInfo.Fields = append(typeInfo.Fields, field)
	}

	g.types[name] = typeInfo
}

func (g *codeGenerator) processSimpleType(name string, st *SimpleType, ns string) {
	if st == nil || st.Restriction == nil {
		return
	}

	rest := st.Restriction

	// Check if it's an enumeration
	if len(rest.Enumerations) > 0 {
		typeInfo := &TypeInfo{
			Name:     name,
			IsPublic: g.makePublic || isInitialCapital(name),
			IsEnum:   true,
			EnumValues: []EnumValue{},
		}

		for _, enum := range rest.Enumerations {
			ev := EnumValue{
				Name:  name + stringToUpperCamel(enum.Value),
				Value: enum.Value,
			}
			if enum.Annotation != nil && enum.Annotation.Documentation != nil {
				ev.Comment = enum.Annotation.Documentation.Text
			}
			typeInfo.EnumValues = append(typeInfo.EnumValues, ev)
		}

		g.types[name] = typeInfo
	} else {
		// Simple type alias
		baseType := g.goType(rest.Base)
		typeInfo := &TypeInfo{
			Name:     name,
			IsPublic: g.makePublic || isInitialCapital(name),
			Fields: []Field{
				{
					Name: "Value",
					Type: baseType,
				},
			},
		}
		g.types[name] = typeInfo
	}
}

func (g *codeGenerator) addElementType(name, typeRef, ns, comment string) {
	// This handles element references
	typeInfo := &TypeInfo{
		Name:     name,
		IsPublic: g.makePublic || isInitialCapital(name),
		Fields: []Field{
			{
				Name: "Value",
				Type: g.goType(typeRef),
			},
		},
	}
	g.types[name] = typeInfo
}

func (g *codeGenerator) generateType(typeInfo *TypeInfo) string {
	var sb strings.Builder

	if typeInfo.IsEnum {
		sb.WriteString(fmt.Sprintf("type %s string\n\n", typeInfo.Name))
		sb.WriteString("const (\n")
		for _, ev := range typeInfo.EnumValues {
			if ev.Comment != "" {
				sb.WriteString(fmt.Sprintf("\t// %s\n", ev.Comment))
			}
			sb.WriteString(fmt.Sprintf("\t%s %s = \"%s\"\n", ev.Name, typeInfo.Name, ev.Value))
		}
		sb.WriteString(")\n\n")
	} else {
		sb.WriteString(fmt.Sprintf("type %s struct {\n", typeInfo.Name))
		sb.WriteString("\tXMLName xml.Name `xml:\"" + getNamespaceForType(g.wsdl, typeInfo.Name) + " " + typeInfo.Name + "\"`\n\n")

		for _, field := range typeInfo.Fields {
			if field.Comment != "" {
				sb.WriteString(fmt.Sprintf("\t// %s\n", field.Comment))
			}
			sb.WriteString(fmt.Sprintf("\t%s %s `xml:\"%s\" json:\"%s\"`\n", 
				field.Name, field.Type, field.XMLTag, field.JSONTag))
		}

		sb.WriteString("}\n\n")
	}

	return sb.String()
}

func (g *codeGenerator) generateServices() string {
	var sb strings.Builder

	if g.wsdl.PortTypes != nil {
		for _, pt := range g.wsdl.PortTypes {
			sb.WriteString(g.generatePortType(pt))
		}
	}

	return sb.String()
}

func (g *codeGenerator) generatePortType(pt PortType) string {
	var sb strings.Builder

	interfaceName := pt.Name
	implName := strings.ToLower(string(rune(interfaceName[0]))) + interfaceName[1:]

	// Generate interface
	sb.WriteString(fmt.Sprintf("type %s interface {\n", interfaceName))
	for _, op := range pt.Operations {
		// Get input and output types from messages
		inputType, outputType := g.getOperationTypes(op)
		sb.WriteString(fmt.Sprintf("\t%s(request *%s) (*%s, error)\n\n", 
			op.Name, inputType, outputType))
		sb.WriteString(fmt.Sprintf("\t%sContext(ctx context.Context, request *%s) (*%s, error)\n", 
			op.Name, inputType, outputType))
	}
	sb.WriteString("}\n\n")

	// Generate implementation struct
	sb.WriteString(fmt.Sprintf("type %s struct {\n", implName))
	sb.WriteString("\tclient *soap.Client\n")
	sb.WriteString("}\n\n")

	// Generate constructor
	sb.WriteString(fmt.Sprintf("func New%s(client *soap.Client) %s {\n", 
		interfaceName, interfaceName))
	sb.WriteString(fmt.Sprintf("\treturn &%s{\n", implName))
	sb.WriteString("\t\tclient: client,\n")
	sb.WriteString("\t}\n")
	sb.WriteString("}\n\n")

	// Generate methods
	for _, op := range pt.Operations {
		inputType, outputType := g.getOperationTypes(op)
		soapAction := g.getSoapAction(op.Name)

		// Context version
		sb.WriteString(fmt.Sprintf("func (service *%s) %sContext(ctx context.Context, request *%s) (*%s, error) {\n",
			implName, op.Name, inputType, outputType))
		sb.WriteString(fmt.Sprintf("\tresponse := new(%s)\n", outputType))
		sb.WriteString(fmt.Sprintf("\terr := service.client.CallContext(ctx, \"%s\", request, response)\n", soapAction))
		sb.WriteString("\tif err != nil {\n")
		sb.WriteString("\t\treturn nil, err\n")
		sb.WriteString("\t}\n\n")
		sb.WriteString("\treturn response, nil\n")
		sb.WriteString("}\n\n")

		// Non-context version
		sb.WriteString(fmt.Sprintf("func (service *%s) %s(request *%s) (*%s, error) {\n",
			implName, op.Name, inputType, outputType))
		sb.WriteString(fmt.Sprintf("\treturn service.%sContext(\n", op.Name))
		sb.WriteString("\t\tcontext.Background(),\n")
		sb.WriteString("\t\trequest,\n")
		sb.WriteString("\t)\n")
		sb.WriteString("}\n\n")
	}

	return sb.String()
}

func (g *codeGenerator) getOperationTypes(op Operation) (string, string) {
	// Find message definitions
	inputType := "interface{}"
	outputType := "interface{}"

	// Parse message references
	inputMsg := op.Input.Message
	outputMsg := op.Output.Message

	if inputMsg != "" {
		inputMsg = strings.TrimPrefix(inputMsg, "tns:")
		if msg := g.findMessage(inputMsg); msg != nil {
			inputType = g.getMessageElementType(msg)
		}
	}

	if outputMsg != "" {
		outputMsg = strings.TrimPrefix(outputMsg, "tns:")
		if msg := g.findMessage(outputMsg); msg != nil {
			outputType = g.getMessageElementType(msg)
		}
	}

	return inputType, outputType
}

func (g *codeGenerator) findMessage(name string) *Message {
	if g.wsdl.Messages == nil {
		return nil
	}
	for i := range g.wsdl.Messages {
		if g.wsdl.Messages[i].Name == name {
			return &g.wsdl.Messages[i]
		}
	}
	return nil
}

func (g *codeGenerator) getMessageElementType(msg *Message) string {
	if msg == nil || len(msg.Parts) == 0 {
		return "interface{}"
	}

	part := msg.Parts[0]
	if part.Element != "" {
		// Remove namespace prefix
		elem := strings.TrimPrefix(part.Element, "xsd1:")
		elem = strings.TrimPrefix(elem, "tns:")
		return elem
	}
	if part.Type != "" {
		return g.goType(part.Type)
	}

	return "interface{}"
}

func (g *codeGenerator) getSoapAction(opName string) string {
	// Try to find soap:operation soapAction in binding
	// For now, return empty string which means use the operation name
	return ""
}

func (g *codeGenerator) generateSOAPStructures() string {
	var sb strings.Builder

	// Generate SOAP envelope request
	sb.WriteString("type SOAPEnvelopeRequest struct {\n")
	sb.WriteString("\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Envelope\"`\n")
	sb.WriteString("\tBody    SOAPBodyRequest\n")
	sb.WriteString("}\n\n")

	// Generate SOAP body request
	sb.WriteString("type SOAPBodyRequest struct {\n")
	sb.WriteString("\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Body\"`\n\n")

	// Add request element types
	if g.wsdl.PortTypes != nil {
		for _, pt := range g.wsdl.PortTypes {
			for _, op := range pt.Operations {
				inputType, _ := g.getOperationTypes(op)
				// Use the message element name
				elemName := g.getMessageElementName(op.Input.Message)
				if elemName != "" {
					sb.WriteString(fmt.Sprintf("\t%s *%s `xml:,omitempty`\n", elemName, inputType))
				}
			}
		}
	}
	sb.WriteString("}\n\n")

	// Generate SOAP envelope response
	sb.WriteString("type SOAPEnvelopeResponse struct {\n")
	sb.WriteString("\tXMLName    xml.Name `xml:\"soap:Envelope\"`\n")
	sb.WriteString("\tPrefixSoap string   `xml:\"xmlns:soap,attr\"`\n")
	sb.WriteString("\tPrefixXsi  string   `xml:\"xmlns:xsi,attr\"`\n")
	sb.WriteString("\tPrefixXsd  string   `xml:\"xmlns:xsd,attr\"`\n\n")
	sb.WriteString("\tBody SOAPBodyResponse\n")
	sb.WriteString("}\n\n")

	sb.WriteString("func NewSOAPEnvelopResponse() *SOAPEnvelopeResponse {\n")
	sb.WriteString("\treturn &SOAPEnvelopeResponse{\n")
	sb.WriteString("\t\tPrefixSoap: \"http://schemas.xmlsoap.org/soap/envelope/\",\n")
	sb.WriteString("\t\tPrefixXsd:  \"http://www.w3.org/2001/XMLSchema\",\n")
	sb.WriteString("\t\tPrefixXsi:  \"http://www.w3.org/2001/XMLSchema-instance\",\n")
	sb.WriteString("\t}\n")
	sb.WriteString("}\n\n")

	// Generate Fault type
	sb.WriteString("type Fault struct {\n")
	sb.WriteString("\tXMLName xml.Name `xml:\"SOAP-ENV:Fault\"`\n")
	sb.WriteString("\tSpace   string   `xml:\"xmlns:SOAP-ENV,omitempty,attr\"`\n\n")
	sb.WriteString("\tCode   string `xml:\"faultcode,omitempty\"`\n")
	sb.WriteString("\tString string `xml:\"faultstring,omitempty\"`\n")
	sb.WriteString("\tActor  string `xml:\"faultactor,omitempty\"`\n")
	sb.WriteString("\tDetail string `xml:\"detail,omitempty\"`\n")
	sb.WriteString("}\n\n")

	// Generate SOAP body response
	sb.WriteString("type SOAPBodyResponse struct {\n")
	sb.WriteString("\tXMLName xml.Name `xml:\"soap:Body\"`\n")
	sb.WriteString("\tFault   *Fault   `xml:\",omitempty\"`\n\n")

	// Add response element types
	if g.wsdl.PortTypes != nil {
		for _, pt := range g.wsdl.PortTypes {
			for _, op := range pt.Operations {
				_, outputType := g.getOperationTypes(op)
				elemName := g.getMessageElementName(op.Output.Message)
				if elemName != "" {
					sb.WriteString(fmt.Sprintf("\t%s *%s `xml:\",omitempty\"`\n", elemName, outputType))
				}
			}
		}
	}
	sb.WriteString("}\n\n")

	return sb.String()
}

func (g *codeGenerator) getMessageElementName(msgRef string) string {
	// Find the message and get its element name
	msgName := strings.TrimPrefix(msgRef, "tns:")
	if msg := g.findMessage(msgName); msg != nil {
		if len(msg.Parts) > 0 && msg.Parts[0].Element != "" {
			return strings.TrimPrefix(msg.Parts[0].Element, "xsd1:")
		}
	}
	return msgName
}

func (g *codeGenerator) generateServerHandlers() string {
	var sb strings.Builder

	// Generate service interface implementation stubs
	if g.wsdl.PortTypes != nil {
		for _, pt := range g.wsdl.PortTypes {
			for _, op := range pt.Operations {
				inputType, outputType := g.getOperationTypes(op)
				sb.WriteString(fmt.Sprintf("func (service *SOAPBodyRequest) %sFunc(request *%s) (*%s, error) {\n",
					op.Name, inputType, outputType))
				sb.WriteString("\treturn nil, WSDLUndefinedError\n")
				sb.WriteString("}\n\n")
			}
		}
	}

	// Generate main handler
	sb.WriteString("func (service *SOAPEnvelopeRequest) call(w http.ResponseWriter, r *http.Request) {\n")
	sb.WriteString("\tw.Header().Add(\"Content-Type\", \"text/xml; charset=utf-8\")\n")
	sb.WriteString("\tval := reflect.ValueOf(&service.Body).Elem()\n")
	sb.WriteString("\tn := val.NumField()\n")
	sb.WriteString("\tvar field reflect.Value\n")
	sb.WriteString("\tvar name string\n")
	sb.WriteString("\tfind := false\n\n")

	sb.WriteString("\tif r.Method == http.MethodGet {\n")
	sb.WriteString("\t\tw.Write([]byte(wsdl))\n")
	sb.WriteString("\t\treturn\n")
	sb.WriteString("\t}\n\n")

	sb.WriteString("\tresp := NewSOAPEnvelopResponse()\n")
	sb.WriteString("\tdefer func() {\n")
	sb.WriteString("\t\tif r := recover(); r != nil {\n")
	sb.WriteString("\t\t\tresp.Body.Fault = &Fault{}\n")
	sb.WriteString("\t\t\tresp.Body.Fault.Space = \"http://schemas.xmlsoap.org/soap/envelope/\"\n")
	sb.WriteString("\t\t\tresp.Body.Fault.Code = \"soap:Server\"\n")
	sb.WriteString("\t\t\tresp.Body.Fault.Detail = fmt.Sprintf(\"%v\", r)\n")
	sb.WriteString("\t\t\tresp.Body.Fault.String = fmt.Sprintf(\"%v\", r)\n")
	sb.WriteString("\t\t}\n")
	sb.WriteString("\t\txml.NewEncoder(w).Encode(resp)\n")
	sb.WriteString("\t}()\n\n")

	sb.WriteString("\theader := r.Header.Get(\"Content-Type\")\n")
	sb.WriteString("\tif strings.Index(header, \"application/soap+xml\") >= 0 {\n")
	sb.WriteString("\t\tpanic(\"Could not find an appropriate Transport Binding to invoke.\")\n")
	sb.WriteString("\t}\n\n")

	sb.WriteString("\terr := xml.NewDecoder(r.Body).Decode(service)\n")
	sb.WriteString("\tif err != nil {\n")
	sb.WriteString("\t\tpanic(err)\n")
	sb.WriteString("\t}\n\n")

	sb.WriteString("\tfor i := 0; i < n; i++ {\n")
	sb.WriteString("\t\tfield = val.Field(i)\n")
	sb.WriteString("\t\tname = val.Type().Field(i).Name\n")
	sb.WriteString("\t\tif field.Kind() != reflect.Ptr {\n")
	sb.WriteString("\t\t\tcontinue\n")
	sb.WriteString("\t\t}\n")
	sb.WriteString("\t\tif field.IsNil() {\n")
	sb.WriteString("\t\t\tcontinue\n")
	sb.WriteString("\t\t}\n")
	sb.WriteString("\t\tif field.IsValid() {\n")
	sb.WriteString("\t\t\tfind = true\n")
	sb.WriteString("\t\t\tbreak\n")
	sb.WriteString("\t\t}\n")
	sb.WriteString("\t}\n\n")

	sb.WriteString("\tif !find {\n")
	sb.WriteString("\t\tpanic(WSDLUndefinedError)\n")
	sb.WriteString("\t} else {\n")
	sb.WriteString("\t\tm := val.Addr().MethodByName(name + \"Func\")\n")
	sb.WriteString("\t\tif !m.IsValid() {\n")
	sb.WriteString("\t\t\tpanic(WSDLUndefinedError)\n")
	sb.WriteString("\t\t}\n\n")
	sb.WriteString("\t\tvals := m.Call([]reflect.Value{field})\n")
	sb.WriteString("\t\tif vals[1].IsNil() {\n")
	sb.WriteString("\t\t\treflect.ValueOf(&resp.Body).Elem().FieldByName(name).Set(vals[0])\n")
	sb.WriteString("\t\t} else {\n")
	sb.WriteString("\t\t\tpanic(vals[1].Interface())\n")
	sb.WriteString("\t\t}\n")
	sb.WriteString("\t}\n")
	sb.WriteString("}\n\n")

	sb.WriteString("func Endpoint(w http.ResponseWriter, r *http.Request) {\n")
	sb.WriteString("\trequest := SOAPEnvelopeRequest{}\n")
	sb.WriteString("\trequest.call(w, r)\n")
	sb.WriteString("}\n")

	return sb.String()
}

func (g *codeGenerator) goType(xsdType string) string {
	// Remove namespace prefix
	t := strings.TrimPrefix(xsdType, "s:")
	t = strings.TrimPrefix(t, "xsd:")
	t = strings.TrimPrefix(t, "xsd1:")
	t = strings.TrimPrefix(t, "tns:")

	switch t {
	case "string":
		return "string"
	case "int":
		return "int"
	case "integer":
		return "int"
	case "float":
		return "float32"
	case "double":
		return "float64"
	case "boolean":
		return "bool"
	case "dateTime":
		return "soap.XSDDateTime"
	case "date":
		return "soap.XSDDate"
	default:
		return t
	}
}

func getNamespaceForType(wsdl *WSDL, typeName string) string {
	// Find the namespace for this type
	if wsdl.Types != nil {
		for _, schema := range wsdl.Types.Schemas {
			for _, elem := range schema.Elements {
				if elem.Name == typeName {
					return schema.TargetNamespace
				}
			}
			for _, ct := range schema.ComplexTypes {
				if ct.Name == typeName {
					return schema.TargetNamespace
				}
			}
		}
	}
	return ""
}

func isInitialCapital(s string) bool {
	if len(s) == 0 {
		return false
	}
	return s[0] >= 'A' && s[0] <= 'Z'
}

func stringToUpperCamel(s string) string {
	// Convert snake_case or spaces to CamelCase
	parts := strings.FieldsFunc(s, func(r rune) bool {
		return r == '_' || r == ' ' || r == '-'
	})

	result := ""
	for _, p := range parts {
		if len(p) > 0 {
			result += strings.ToUpper(string(p[0])) + p[1:]
		}
	}

	// If no changes, just capitalize first letter
	if result == "" && len(s) > 0 {
		result = strings.ToUpper(string(s[0])) + s[1:]
	}

	return result
}
