package main

import (
	"strings"
	"unicode"
)

// toCamelCase converts snake_case or camelCase to proper exported CamelCase
func toCamelCase(s string) string {
	if len(s) == 0 {
		return s
	}

	// First check if it's already camelCase (first letter lowercase, followed by uppercase letter)
	// or snake_case

	if strings.Contains(s, "_") {
		// Snake case - convert to CamelCase
		parts := strings.Split(s, "_")
		result := ""
		for _, part := range parts {
			if len(part) > 0 {
				result += strings.ToUpper(string(part[0])) + part[1:]
			}
		}
		return result
	}

	// For already camelCase or regular names, capitalize the first letter
	if len(s) > 0 {
		first := string(s[0])
		if first == strings.ToLower(first) && first != strings.ToUpper(first) {
			// First character is lowercase
			return strings.ToUpper(first) + s[1:]
		}
	}

	return s
}

// The exported version for struct fields
func toExportedFieldName(fieldName string) string {
	result := toCamelCase(fieldName)
	// Ensure first character is uppercase for export
	if len(result) > 0 {
		return strings.ToUpper(string(result[0])) + result[1:]
	}
	return result
}
EOF

