package main

import (
	"strings"
)

// getSoapActionForOperation finds the soap:operation soapAction for a given operation
func (g *codeGenerator) getSoapActionForOperation(opName string) string {
	if g.wsdl.Bindings == nil {
		return ""
	}

	for _, binding := range g.wsdl.Bindings {
		for _, operation := range binding.Operations {
			if operation.Name == opName {
				return operation.SoapAction
			}
		}
	}

	return ""
