package main

import (
	"strings"
	"unicode"
)

// exportName converts a name to an exported (public) name in Go
func (g *codeGenerator) exportName(name string) string {
	if !g.makePublic {
		return name
	}

	if len(name) == 0 {
		return name
	}

	// Capitalize first letter
	first := rune(name[0])
	if unicode.IsLower(first) {
		return strings.ToUpper(string(first)) + name[1:]
	}

	return name
}

// fieldName converts a field name to an exported Go struct field name
func fieldName(name string) string {
	if len(name) == 0 {
		return name
	}

	// Capitalize first letter for struct fields (Go requirement)
	first := rune(name[0])
	if unicode.IsLower(first) {
		return strings.ToUpper(string(first)) + name[1:]
	}

	return name
}
EOF

