package main

import (
	"encoding/xml"
	"fmt"
	"strings"
)

// StructField represents a field in a generated Go struct
type StructField struct {
	Name       string
	Type       string
	XMLTag     string
	JSONTag    string
	Comment    string
	IsArray    bool
	IsInline   bool
	InlineType *InlineType
}

// InlineType represents an inline struct type
type InlineType struct {
	Fields []StructField
}

// parseComplexTypeDetails parses a complex type and returns structured field information
func parseComplexTypeDetails(elem xml.Encoder, name string, ct *ComplexType, ns string) []StructField {
	fields := []StructField{}

	// Handle sequence
	if ct.Sequence != nil {
		for _, elem := range ct.Sequence.Elements {
			field := parseElement(elem, ns)
			fields = append(fields, field)
		}
	}

	// Handle all
	if ct.All != nil {
		for _, elem := range ct.All.Elements {
			field := parseElement(elem, ns)
			fields = append(fields, field)
		}
	}

	// Handle simple content with extension
	if ct.SimpleContent != nil && ct.SimpleContent.Extension != nil {
		ext := ct.SimpleContent.Extension

		// Add the text value field
		fields = append(fields, StructField{
			Name:    "Value",
			Type:    goTypeFromXSD(ext.Base),
			XMLTag:  ",chardata",
			JSONTag: "-,",
		})

		// Add attributes
		for _, attr := range ext.Attributes {
			field := parseAttribute(attr, ns)
			fields = append(fields, field)
		}
	}

	// Handle standalone attributes
	for _, attr := range ct.Attributes {
		field := parseAttribute(attr, ns)
		fields = append(fields, field)
	}

	return fields
}

func parseElement(elem Element, ns string) StructField {
	field := StructField{
		Name: fieldName(elem.Name),
		XMLTag: elem.Name,
		JSONTag: elem.Name,
	}

	// Handle maxOccurs for arrays
	if elem.MaxOccurs == "unbounded" {
		field.IsArray = true
		field.XMLTag += ",omitempty"
		field.JSONTag += ",omitempty"
	} else {
		field.XMLTag += ",omitempty"
		field.JSONTag += ",omitempty"
	}

	// Determine type
	if elem.ComplexType != nil {
		// Inline complex type - need to handle this specially
		field.IsInline = true
		// For now, use a placeholder
		field.Type = "interface{}"
	} else if elem.SimpleType != nil {
		field.Type = goTypeFromSimpleType(elem.SimpleType)
	} else if elem.Type != "" {
		field.Type = goTypeFromXSD(elem.Type)
	}

	// Extract documentation
	if elem.Annotation != nil && elem.Annotation.Documentation != nil {
		field.Comment = elem.Annotation.Documentation.Text
	}

	return field
}

func parseAttribute(attr Attribute, ns string) StructField {
	field := StructField{
		Name:    fieldName(attr.Name),
		XMLTag:  attr.Name + ",attr,omitempty",
		JSONTag: attr.Name + ",omitempty",
	}

	if attr.Type != "" {
		field.Type = goTypeFromXSD(attr.Type)
	} else if attr.Ref != "" {
		// Reference to a global attribute - extract the name
		refName := strings.TrimPrefix(attr.Ref, "tns:")
		field.Type = goTypeFromXSD(refName)
		field.XMLTag = ns + " " + refName + ",attr,omitempty"
	} else if attr.SimpleType != nil {
		field.Type = goTypeFromSimpleType(attr.SimpleType)
	}

	return field
}

func goTypeFromSimpleType(st *SimpleType) string {
	if st == nil || st.Restriction == nil {
		return "string"
	}

	return goTypeFromXSD(st.Restriction.Base)
}

func goTypeFromXSD(xsdType string) string {
	// Remove namespace prefix
	t := strings.TrimPrefix(xsdType, "s:")
	t = strings.TrimPrefix(t, "xsd:")
	t = strings.TrimPrefix(t, "xsd1:")
	t = strings.TrimPrefix(t, "tns:")

	switch t {
	case "string":
		return "string"
	case "int", "integer":
		return "int"
	case "float":
		return "float32"
	case "double":
		return "float64"
	case "boolean":
		return "bool"
	case "dateTime":
		return "soap.XSDDateTime"
	case "date":
		return "soap.XSDDate"
	default:
		return t
	}
}
EOF

