package main

import (
	"strings"
	"unicode"
)

// exportName ensures a name is exported (public) if makePublic is true
// Otherwise returns the name as-is
func (g *codeGenerator) exportName(name string) string {
	if !g.makePublic {
		return name
	}

	return toExportedName(name)
}

// toExportedName capitalizes the first letter of a name
func toExportedName(name string) string {
	if len(name) == 0 {
		return name
	}

	first := rune(name[0])
	if unicode.IsLower(first) {
		return strings.ToUpper(string(first)) + name[1:]
	}

	return name
}
EOF

